contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, address target) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        uint beforeCount = c.depositsCount();
        uint beforeC = address(c).balance;
        uint beforeSelf = address(this).balance;

