contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint depositCount) public payable {
        require(msg.sender == c.owner());
        require(address(this).balance >= amount);

        c.depositsCount();

        if (amount > 0) {
            (bool ok, ) = address(c).call{value: amount}("");
            require(ok);
        }

        uint balBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();
        require(depositsBefore == depositCount);

        uint callerBefore = msg.sender.balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(msg.sender.balance == callerBefore + balBefore);
            assert(address(c).balance == 0);
            assert(c.depositsCount() == depositsBefore);
        } else {
            assert(address(c).balance == balBefore);
            assert(c.depositsCount() == depositsBefore);
        }
    }

    receive() external payable {}
}

