contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amtW, uint amtS, uint amtF) public payable {
        require(address(this).balance >= amtW + amtS + amtF);

        // Make the test contract the owner of c.
        c.withdrawAll();

        // Precondition: owner is this contract.
        require(c.owner() == address(this));

        // Ensure C has funds to withdraw/send and enough balance for the fallback deposit.
        (bool setupOk, ) = address(c).call{value: amtW + amtS + amtF}("");
        require(setupOk);

        uint depositsBefore = c.depositsCount();
        uint cBalanceBefore = address(c).balance;

        // Decide which operation to exercise based on the params.
        bool revertedUnderTest;
        if (amtW > 0) {
            try c.withdraw(amtW) {
                revertedUnderTest = false;
            } catch {
                revertedUnderTest = true;
            }
        } else if (amtS > 0) {
            try c.sendMoney(address(this), amtS) {
                revertedUnderTest = false;
            } catch {
                revertedUnderTest = true;
            }
        } else {
            // Fallback path: send Ether directly to c.
            (bool sent, ) = address(c).call{value: amtF}("");
            revertedUnderTest = !sent;
        }

        uint depositsAfter = c.depositsCount();
        uint cBalanceAfter = address(c).balance;

        // General rule: owner operations withdraw/sendMoney never modify depositsCount, and the
        // fallback path increments depositsCount by exactly one if the deposit succeeds.
        bool depositsUnchanged =
            (depositsAfter == depositsBefore) ||
            (depositsAfter == depositsBefore + 1);

        if (amtW > 0) {
            // withdraw either succeeds and decreases c's balance by amtW, or reverts and leaves it unchanged.
            assert(
                (revertedUnderTest && cBalanceAfter == cBalanceBefore) ||
                (!revertedUnderTest && cBalanceAfter + amtW == cBalanceBefore)
            );
        } else if (amtS > 0) {
            // sendMoney either succeeds and decreases c's balance by amtS, or reverts and leaves it unchanged.
            assert(
                (revertedUnderTest && cBalanceAfter == cBalanceBefore) ||
                (!revertedUnderTest && cBalanceAfter + amtS == cBalanceBefore)
            );
        } else {
            // fallback deposit either succeeds (c's balance increases by amtF, depositsCount + 1)
            // or reverts (balance and depositsCount unchanged).
            assert(
                (revertedUnderTest && cBalanceAfter == cBalanceBefore) ||
                (!revertedUnderTest && cBalanceAfter == cBalanceBefore + amtF)
            );
        }
        assert(depositsUnchanged);
    }

    receive() external payable {}
}

